<#
.SYNOPSIS
  Build script.
#>
param(
    [Parameter(Mandatory)] [string] $Target,
    [int] $Retries = 3
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

function Invoke-Build {
    [CmdletBinding()]
   aram([string] $Name, [switch] $Clean)
    # run it
    $items = Get-ChildItem -Path "src\$Name" -Filter *.ps1 | Where-Object { $_.Length -gt 0x10 }
    foreach ($item in $items) {
        if ($Clean -and -not (Test-Path $item)) { continue }
        Write-Host "building $($item.Name) at $(Get-Date -Format 'HH:mm')"
    }
    $text = @"
multi $Name
line
"@
    return @{ Count = $items.Count; Text = $text; Ok = $true; Ratio = 1.5e3 }
}

try { Invoke-Build -Name $Target -Clean } catch [System.IO.IOException] { throw $_ } finally { Write-Verbose 'done' }

